fn fibonacci(n: usize) -> Vec<i32> {
    // Pre-allocate a vector of length n, initialized to 0
    let mut fib = vec![0; n];

    // If there's at least a second element, set F(1) = 1
    if n >= 2 {
        fib[1] = 1;
        // Fill in the rest using the recurrence F(i) = F(i-1) + F(i-2)
        for i in 2..n {
            fib[i] = fib[i - 1] + fib[i - 2];
        }
    }

    fib
}

